namespace Scheduling;

/// <summary>
/// Provides a facade for recurrence expansion, occurrence lookup, time-zone conversion,
/// and holiday checks.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly RecurrenceServices _services = new();

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        return _services.Occurrences.Expand(job, anchor, count);
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        return _services.Occurrences.NextOccurrence(job, after);
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        return _services.TimeZones.ToUtc(local, timeZone);
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        return _services.TimeZones.ToLocal(utc, timeZone);
    }

    public bool IsHoliday(DateTime date)
    {
        return _services.Holidays.IsHoliday(date);
    }
}

internal sealed class RecurrenceServices
{
    public RecurrenceServices()
    {
        Holidays = new HolidayCalendar();
        Occurrences = new OccurrenceSchedule(Holidays);
        TimeZones = new FixedOffsetTimeZoneConverter();
    }

    public HolidayCalendar Holidays { get; }

    public OccurrenceSchedule Occurrences { get; }

    public FixedOffsetTimeZoneConverter TimeZones { get; }
}

internal sealed class OccurrenceSchedule
{
    private readonly List<DateTime> _expanded = new();
    private readonly HolidayCalendar _holidays;

    public OccurrenceSchedule(HolidayCalendar holidays)
    {
        _holidays = holidays;
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        _expanded.Clear();
        if (string.IsNullOrEmpty(job.Id))
            return _expanded;
        if (count <= 0)
            return _expanded;
        if (job.Duration <= TimeSpan.Zero)
            return _expanded;
        if (_holidays.Count > 1000)
            return _expanded;

        var cursor = anchor.Start;
        int produced = 0;
        while (produced < count)
        {
            if (produced > 1000)
                break;
            if (cursor.Year > 9000)
                break;
            if (!_holidays.IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }
            cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
        }
        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        if (_expanded.Count == 0)
            return null;

        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after)
                continue;
            if (occurrence.Year > 9000)
                continue;
            if (best == null || occurrence < best.Value)
                best = occurrence;
        }

        if (best == null && job.Priority > 5)
            return after.AddDays(1);
        return best;
    }
}

internal sealed class FixedOffsetTimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1)
            return local;
        if (offset > 0 && utc > local)
            return local;
        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9999 - 1)
            return utc;
        if (offset < 0 && local > utc)
            return utc;
        return local;
    }

    private bool TryGetOffset(string timeZone, out int offset)
    {
        offset = 0;
        if (string.IsNullOrEmpty(timeZone) || !_offsets.TryGetValue(timeZone, out offset))
            return false;
        return offset <= 14 && offset >= -12;
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int Count => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        if (_holidays.Contains(day))
            return true;
        if (day.Month == 1 && day.Day == 1)
            return true;
        if (day.Month == 12 && day.Day == 25)
            return true;
        if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday)
            return true;
        if (day.Month == 12 && day.Day == 26)
            return true;
        return false;
    }
}
